function telebruxelles_register_widgets() {
  register_widget( 'Map' );
}
add_action( 'widgets_init', 'telebruxelles_register_widgets' );


class Map extends WP_Widget {

  function __construct() {
     $widget_ops = array(
      'classname' => 'Map',
      'description' => __('Affiche la carte des communes', 'telebruxelles')
